    22	/**
    23	 * Grab the appropriate receipt image and thumbnail URIs based on file type
    24	 *
    25	 * @param transaction
    26	 * @param receiptPath
    27	 * @param receiptFileName
    28	 */
    29	function getThumbnailAndImageURIs(transaction: OnyxEntry<Transaction>, receiptPath: ReceiptSource | null = null, receiptFileName: string | null = null): ThumbnailAndImageURI {
    30	    if (!TransactionUtils.hasReceipt(transaction) && !receiptPath && !receiptFileName) {
    31	        return {isEmptyReceipt: true};
    32	    }
    33	    if (TransactionUtils.isFetchingWaypointsFromServer(transaction)) {
    34	        return {isThumbnail: true, isLocalFile: true};
    35	    }
    36	    // If there're errors, we need to display them in preview. We can store many files in errors, but we just need to get the last one
    37	    const errors = findLast(transaction?.errors) as ReceiptError | undefined;
    38	    // URI to image, i.e. blob:new.expensify.com/9ef3a018-4067-47c6-b29f-5f1bd35f213d or expensify.com/receipts/w_e616108497ef940b7210ec6beb5a462d01a878f4.jpg
    39	    const path = errors?.source ?? transaction?.receipt?.source ?? receiptPath ?? '';
    40	    // filename of uploaded image or last part of remote URI
    41	    const filename = errors?.filename ?? transaction?.filename ?? receiptFileName ?? '';
    42	    const isReceiptImage = Str.isImage(filename);
    43	    const hasEReceipt = !TransactionUtils.hasReceiptSource(transaction) && transaction?.hasEReceipt;
    44	    const isReceiptPDF = Str.isPDF(filename);
    45	
    46	    if (hasEReceipt) {
    47	        return {image: ROUTES.ERECEIPT.getRoute(transaction.transactionID), transaction, filename};
    48	    }
