    50	    // For local files, we won't have a thumbnail yet
    51	    if ((isReceiptImage || isReceiptPDF) && typeof path === 'string' && (path.startsWith('blob:') || path.startsWith('file:'))) {
    52	        return {image: path, isLocalFile: true, filename};
    53	    }
